CREATE TABLE product_weight_provenance (
  record_id TEXT PRIMARY KEY REFERENCES products(record_id) ON DELETE CASCADE,
  match_method TEXT NOT NULL CHECK (match_method IN ('exact_code', 'name_similarity')),
  source_workbook TEXT NOT NULL,
  source_sheet TEXT NOT NULL,
  source_row INTEGER NOT NULL,
  source_product_code TEXT,
  source_product_name_zh TEXT NOT NULL,
  gross_weight_kg REAL NOT NULL CHECK (gross_weight_kg > 0),
  units_per_carton REAL NOT NULL CHECK (units_per_carton > 0),
  unit_weight_kg REAL NOT NULL CHECK (unit_weight_kg > 0),
  name_similarity_score REAL,
  source_in_license INTEGER NOT NULL CHECK (source_in_license IN (0, 1)),
  source_code_contains_sym INTEGER NOT NULL CHECK (source_code_contains_sym IN (0, 1)),
  matched_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE rollback_0003_product_weights (
  record_id TEXT PRIMARY KEY,
  unit_weight_kg REAL,
  unit_weight_source TEXT,
  updated_at TEXT NOT NULL
);

SELECT p.record_id, p.unit_weight_kg, p.unit_weight_source, p.updated_at
FROM products p
JOIN category_products cp ON cp.record_id = p.record_id
WHERE EXISTS (
  SELECT 1 FROM category_quotas q
  WHERE q.category_id = cp.category_id AND q.quota_unit_code = 'kg'
);

CREATE TABLE rollback_0003_category_modes (
  id TEXT PRIMARY KEY,
  quantity_mode TEXT NOT NULL
);

SELECT id, quantity_mode
FROM categories
WHERE id IN (SELECT category_id FROM category_quotas WHERE quota_unit_code = 'kg');









UPDATE products
SET unit_weight_kg = (
      SELECT w.unit_weight_kg FROM product_weight_provenance w
      WHERE w.record_id = products.record_id
    ),
    unit_weight_source = 'carton_derived',
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE record_id IN (SELECT record_id FROM product_weight_provenance);

UPDATE categories
SET quantity_mode = 'weight_kg'
WHERE id IN (SELECT category_id FROM category_quotas WHERE quota_unit_code = 'kg');
